<?php

namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Http;use Illuminate\Validation\ValidationException;
class AdminAuthController extends Controller{public function form(){return view('admin.login');}public function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required|string']);$ok=Auth::attempt($c,$r->boolean('remember'));if(!$ok){$key=(string)config('services.firebase.api_key');if($key!==''){$res=Http::asJson()->timeout(10)->post('https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key='.urlencode($key),['email'=>$c['email'],'password'=>$c['password'],'returnSecureToken'=>true]);if($res->successful()&&$res->json('localId')){$uid=(string)$res->json('localId');$user=User::where('legacy_firebase_uid',$uid)->orWhere('firebase_uid',$uid)->orWhereRaw('lower(email)=?',[strtolower($c['email'])])->first();if($user){$user->forceFill(['firebase_uid'=>$uid,'legacy_firebase_uid'=>$uid])->save();$this->syncLegacyAdminRole($user,$uid);Auth::login($user,$r->boolean('remember'));$ok=true;}}}}if(!$ok||!$r->user()?->isAdmin()){Auth::logout();throw ValidationException::withMessages(['email'=>['The credentials are invalid or this account is not an administrator.']]);}$r->session()->regenerate();return redirect()->intended('/admin');}private function syncLegacyAdminRole(User $user,string $uid):void{$row=DB::table('firebase_documents')->where('collection_path','users')->where('document_id',$uid)->first();$payload=$row?json_decode((string)$row->payload,true):[];$claims=is_array($payload['customClaims']??null)?$payload['customClaims']:(is_array($payload['claims']??null)?$payload['claims']:[]);$role=$payload['role']??$claims['role']??null;if($role===null&&($payload['isSuperAdmin']??false))$role='super_admin';if($role===null&&(($payload['isAdmin']??false)||($payload['admin']??false)))$role='admin';$role=strtolower((string)$role);if(in_array($role,['admin','super_admin'],true)&&$user->role!==$role){$user->forceFill(['role'=>$role])->save();DB::table('user_data')->where('user_id',$user->id)->update(['role'=>$role,'updated_at'=>now()]);}}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}}
